$operator=cp51Operator();$csrf=cp51Csrf();$melding='';$fout='';
function hob(string$s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function tob(?string$utc):string{if(!$utc)return'—';try{return(new DateTimeImmutable($utc))->setTimezone(new DateTimeZone('Europe/Amsterdam'))->format('d-m-Y H:i:s');}catch(Throwable$e){return'—';}}
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{cp51CsrfControle((string)($_POST['csrf']??''));if((string)($_POST['action']??'')!=='onboarding-resume')throw new RuntimeException('Onbekende onboardingactie.');$id=cpOnboardResumeRequest($_POST);header('Location: /onboarding.php?queued='.rawurlencode($id),true,303);exit;}catch(Throwable$e){$fout=$e->getMessage();}
}
if(isset($_GET['queued'])&&preg_match('/^[0-9a-f]{32}$/D',(string)$_GET['queued'])===1){$id=(string)$_GET['queued'];$r=cpOnboardRecentResult($id,$operator);if(is_array($r)){if($r['result']==='ok')$melding='Onboardingaanvraag '.substr($id,0,8).' is uitgevoerd. '.$r['message'];else$fout='Onboardingaanvraag '.substr($id,0,8).' is mislukt. '.$r['message'];}else$melding='Onboardingaanvraag '.substr($id,0,8).' staat in de uitvoerqueue of wordt verwerkt. Vernieuw deze pagina voor de uitkomst.';}
