?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Onboarding · Verenigingsplatform</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#17211b;background:#f4f6f4;--green:#1f5f3a;--line:#dbe2dd;--muted:#68746d}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1100px;margin:auto;padding:28px 18px 54px}.top,.head,.actions{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.top{margin-bottom:20px}.actions{align-items:center;flex-wrap:wrap}.eyebrow{font-size:.76rem;text-transform:uppercase;letter-spacing:.08em;color:#607067;font-weight:750}h1{margin:.2rem 0 .35rem;font-size:clamp(1.7rem,3vw,2.3rem)}h2{margin:0;font-size:1.08rem}.muted,.host,.hint{color:var(--muted)}.muted{margin:.35rem 0 0}.host{font-size:.84rem;margin-top:3px}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;border:1px solid #bec9c1;background:#fff;color:#1d2b22;border-radius:9px;padding:9px 11px;font-weight:650;cursor:pointer;font:inherit}.btn.primary{background:var(--green);border-color:var(--green);color:#fff}.btn:disabled{opacity:.48;cursor:not-allowed}.notice{padding:12px 14px;border-radius:10px;margin-bottom:14px}.ok{background:#eaf7ee;border:1px solid #b9dfc2}.err{background:#fff0f0;border:1px solid #efc1c1}.info{background:#eef5ff;border:1px solid #c8dbf2}.grid{display:grid;gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:17px;box-shadow:0 2px 12px rgba(22,40,29,.035)}.badge{border-radius:999px;padding:6px 9px;font-size:.77rem;font-weight:700;background:#eef0ff;color:#4d4b91}.progress{height:8px;background:#e7ece8;border-radius:999px;overflow:hidden;margin:12px 0}.progress span{display:block;height:100%;background:#2c8050}.steps{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;margin:12px 0}.step{border:1px solid #e2e8e3;background:#f8faf8;border-radius:9px;padding:8px;font-size:.78rem}.step.done{background:#edf8f0;border-color:#cde4d3}.step strong{display:block}.security{background:#f7f8ff;border:1px solid #dfe2f2;border-radius:10px;padding:11px;margin-top:12px}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#f1f4f2;border:1px solid #dfe5e0;border-radius:7px;padding:9px;overflow-wrap:anywhere;font-size:.76rem;margin-top:8px}.dns{margin-top:14px;padding-top:13px;border-top:1px solid #edf0ed}.form-grid{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:10px;margin-top:10px}.field label{display:block;font-size:.78rem;font-weight:700;margin-bottom:5px}.field input,.field select{width:100%;border:1px solid #c9d3cc;background:#fff;border-radius:9px;padding:9px 10px;font:inherit}.hint{font-size:.74rem;margin-top:5px}.dns-preview{margin:10px 0;background:#f8faf8;border:1px solid #e3e8e4;border-radius:9px;padding:10px;font-size:.8rem}.foot{margin-top:18px;color:#77817b;font-size:.78rem}.empty{background:#fff;border:1px dashed #cbd4ce;border-radius:13px;padding:24px;text-align:center;color:var(--muted)}@media(max-width:900px){.steps{grid-template-columns:repeat(2,minmax(0,1fr))}.form-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.top{display:block}.actions{margin-top:12px}.steps,.form-grid{grid-template-columns:1fr}}</style></head><body><main class="wrap">
<div class="top"><div><div class="eyebrow">Verenigingsplatform</div><h1>Onboarding hervatten</h1><p class="muted">Eén vaste, hervatbare route van basisprovisioning naar een actieve vereniging. Wachtwoorden en providercredentials blijven buiten de browser.</p></div><div class="actions"><a class="btn" href="/?section=onboarding">← Terug naar beheerconsole</a><span class="badge"><?=hob(control58RoleLabel(cpSuiteRole()))?></span></div></div>
